{
  "name": "Tax Data Blueprint Studio",
  "description": "A modern, canvas-based documentation tool for tax data modeling featuring custom cards, relational mapping, and high-fidelity Excel import/export."
}

export enum NodeCardType {
  TABLE = 'TABLE',
  LOGIC_NOTE = 'LOGIC_NOTE',
  REPORT = 'REPORT'
}

export interface TableColumn {
  id: string;
  name: string;
}

export interface NodeData {
  label: string;
  cardType: NodeCardType;
  columns?: TableColumn[];
  description?: string;
  bulletPoints?: string[];
  onEdit?: (id: string) => void;
  onDelete?: (id: string) => void;
}

export interface EdgeData {
  label?: string;
}

export interface BlueprintProject {
  nodes: any[];
  edges: any[];
  viewport: {
    x: number;
    y: number;
    zoom: number;
  };
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { 
  ReactFlow, 
  Background, 
  Controls, 
  addEdge, 
  applyEdgeChanges, 
  applyNodeChanges,
  Node,
  Edge,
  Connection,
  EdgeChange,
  NodeChange,
  ReactFlowProvider,
  useReactFlow,
  Panel
} from 'reactflow';
import 'reactflow/dist/style.css';
import { Download, Upload, Plus, FileSpreadsheet, Trash2, Edit3, Save } from 'lucide-react';
import * as XLSX from 'xlsx';

import { NodeCardType, NodeData, TableColumn } from './types';
import { BlueprintCard } from './components/BlueprintCard';
import { EditorModal } from './components/EditorModal';

const nodeTypes = {
  blueprintNode: BlueprintCard,
};

const initialNodes: Node<NodeData>[] = [
  {
    id: '1',
    type: 'blueprintNode',
    position: { x: 250, y: 50 },
    data: { 
      label: 'Sales Transactions', 
      cardType: NodeCardType.TABLE,
      columns: [
        { id: '1', name: 'Order ID (PK)' },
        { id: '2', name: 'Amount' },
        { id: '3', name: 'Tax Rate' },
        { id: '4', name: 'Date' }
      ]
    },
  },
  {
    id: '2',
    type: 'blueprintNode',
    position: { x: 600, y: 50 },
    data: { 
      label: 'Invoice Ledger', 
      cardType: NodeCardType.TABLE,
      columns: [
        { id: '1', name: 'Invoice ID (PK)' },
        { id: '2', name: 'Total Price' },
        { id: '3', name: 'Status' }
      ]
    },
  },
  {
    id: '3',
    type: 'blueprintNode',
    position: { x: 425, y: 300 },
    data: { 
      label: 'VAT Calculation', 
      cardType: NodeCardType.LOGIC_NOTE,
      description: 'Calculates the output tax by applying the standard rate to the net sales amount.',
      bulletPoints: ['Standard Rate: 20%', 'Exclude Exempt Sales']
    },
  }
];

const initialEdges: Edge[] = [
  { id: 'e1-3', source: '1', target: '3', label: 'source data' },
  { id: 'e2-3', source: '2', target: '3', label: 'reconciliation' },
];

function BlueprintStudio() {
  const [nodes, setNodes] = useState<Node<NodeData>[]>(initialNodes);
  const [edges, setEdges] = useState<Edge[]>(initialEdges);
  const [editingNode, setEditingNode] = useState<string | null>(null);
  const { setViewport, getViewport, zoomIn, zoomOut } = useReactFlow();

  const onNodesChange = useCallback(
    (changes: NodeChange[]) => setNodes((nds) => applyNodeChanges(changes, nds)),
    []
  );
  const onEdgesChange = useCallback(
    (changes: EdgeChange[]) => setEdges((eds) => applyEdgeChanges(changes, eds)),
    []
  );
  const onConnect = useCallback(
    (params: Connection) => setEdges((eds) => addEdge({ ...params, animated: false }, eds)),
    []
  );

  const handleEdit = (id: string) => {
    setEditingNode(id);
  };

  const handleDelete = (id: string) => {
    setNodes((nds) => nds.filter((node) => node.id !== id));
    setEdges((eds) => eds.filter((edge) => edge.source !== id && edge.target !== id));
  };

  const handleSaveNode = (id: string, updatedData: Partial<NodeData>) => {
    setNodes((nds) =>
      nds.map((node) => {
        if (node.id === id) {
          return { ...node, data: { ...node.data, ...updatedData } };
        }
        return node;
      })
    );
    setEditingNode(null);
  };

  const addNode = (type: NodeCardType) => {
    const id = Date.now().toString();
    const newNode: Node<NodeData> = {
      id,
      type: 'blueprintNode',
      position: { x: 100, y: 100 },
      data: { 
        label: `New ${type.toLowerCase()}`, 
        cardType: type,
        columns: type === NodeCardType.TABLE ? [{ id: '1', name: 'New Column' }] : [],
        description: type === NodeCardType.LOGIC_NOTE ? 'Describe your logic here...' : '',
        bulletPoints: []
      },
    };
    setNodes((nds) => nds.concat(newNode));
  };

  const exportToExcel = () => {
    const nodesSheet = nodes.map(n => ({
      ID: n.id,
      Label: n.data.label,
      Type: n.data.cardType,
      X: n.position.x,
      Y: n.position.y,
      Columns: n.data.columns?.map(c => c.name).join('|') || '',
      Description: n.data.description || '',
      Bullets: n.data.bulletPoints?.join('|') || ''
    }));

    const edgesSheet = edges.map(e => ({
      ID: e.id,
      Source: e.source,
      Target: e.target,
      Label: e.label || ''
    }));

    const wb = XLSX.utils.book_new();
    const ns = XLSX.utils.json_to_sheet(nodesSheet);
    const es = XLSX.utils.json_to_sheet(edgesSheet);
    XLSX.utils.book_append_sheet(wb, ns, "Nodes");
    XLSX.utils.book_append_sheet(wb, es, "Edges");
    XLSX.writeFile(wb, "TaxBlueprint.xlsx");
  };

  const importFromExcel = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const data = evt.target?.result;
      const workbook = XLSX.read(data, { type: 'binary' });

      const nodesData = XLSX.utils.sheet_to_json(workbook.Sheets["Nodes"]) as any[];
      const edgesData = XLSX.utils.sheet_to_json(workbook.Sheets["Edges"]) as any[];

      const newNodes: Node<NodeData>[] = nodesData.map(n => ({
        id: String(n.ID),
        type: 'blueprintNode',
        position: { x: Number(n.X), y: Number(n.Y) },
        data: {
          label: n.Label,
          cardType: n.Type as NodeCardType,
          columns: n.Columns ? n.Columns.split('|').map((name: string, i: number) => ({ id: String(i), name })) : [],
          description: n.Description,
          bulletPoints: n.Bullets ? n.Bullets.split('|') : []
        }
      }));

      const newEdges: Edge[] = edgesData.map(e => ({
        id: String(e.ID),
        source: String(e.Source),
        target: String(e.Target),
        label: e.Label
      }));

      setNodes(newNodes);
      setEdges(newEdges);
    };
    reader.readAsBinaryString(file);
  };

  // Enhance nodes with action callbacks
  const nodesWithActions = nodes.map(node => ({
    ...node,
    data: {
      ...node.data,
      onEdit: handleEdit,
      onDelete: handleDelete,
    }
  }));

  return (
    <div className="w-full h-screen bg-[#f8fafc] flex flex-col">
      {/* Header Toolbar */}
      <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 z-10 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-blue-600 rounded flex items-center justify-center text-white font-bold">T</div>
          <h1 className="text-xl font-semibold text-slate-800 tracking-tight">Tax Data Blueprint Studio</h1>
        </div>

        <div className="flex items-center gap-4">
          <button 
            onClick={() => addNode(NodeCardType.TABLE)}
            className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-700 rounded-lg hover:bg-blue-100 transition-colors font-medium text-sm"
          >
            <Plus size={18} />
            Add Table
          </button>
          <button 
            onClick={() => addNode(NodeCardType.LOGIC_NOTE)}
            className="flex items-center gap-2 px-4 py-2 bg-purple-50 text-purple-700 rounded-lg hover:bg-purple-100 transition-colors font-medium text-sm"
          >
            <Plus size={18} />
            Add Logic Note
          </button>
          <div className="h-6 w-px bg-slate-200 mx-2" />
          <button 
            onClick={exportToExcel}
            className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 text-slate-700 rounded-lg hover:bg-slate-50 transition-colors font-medium text-sm"
          >
            <Download size={18} />
            Export Excel
          </button>
          <label className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 text-slate-700 rounded-lg hover:bg-slate-50 transition-colors font-medium text-sm cursor-pointer">
            <Upload size={18} />
            Import Excel
            <input type="file" className="hidden" accept=".xlsx, .xls" onChange={importFromExcel} />
          </label>
        </div>
      </header>

      {/* Canvas Area */}
      <main className="flex-1 relative overflow-hidden">
        <ReactFlow
          nodes={nodesWithActions}
          edges={edges}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          onConnect={onConnect}
          nodeTypes={nodeTypes}
          fitView
        >
          <Background color="#cbd5e1" variant="dots" gap={20} />
          <Controls />
          <Panel position="bottom-right" className="bg-white p-2 rounded-lg shadow-lg border border-slate-200 flex flex-col gap-2">
            <div className="text-[10px] text-slate-400 font-bold uppercase tracking-wider px-2">Stats</div>
            <div className="flex gap-4 px-2 py-1">
              <div className="flex flex-col">
                <span className="text-sm font-bold text-slate-700">{nodes.length}</span>
                <span className="text-[10px] text-slate-500">Nodes</span>
              </div>
              <div className="flex flex-col">
                <span className="text-sm font-bold text-slate-700">{edges.length}</span>
                <span className="text-[10px] text-slate-500">Connections</span>
              </div>
            </div>
          </Panel>
        </ReactFlow>
      </main>

      {/* Editor Modal */}
      {editingNode && (
        <EditorModal 
          node={nodes.find(n => n.id === editingNode)!} 
          onClose={() => setEditingNode(null)}
          onSave={(data) => handleSaveNode(editingNode, data)}
        />
      )}
    </div>
  );
}

export default function App() {
  return (
    <ReactFlowProvider>
      <BlueprintStudio />
    </ReactFlowProvider>
  );
}

import React, { memo } from 'react';
import { Handle, Position, NodeProps } from 'reactflow';
import { Trash2, Edit3, Database, FileText, BarChart2 } from 'lucide-react';
import { NodeData, NodeCardType } from '../types';

export const BlueprintCard = memo(({ data, id, selected }: NodeProps<NodeData>) => {
  const isTable = data.cardType === NodeCardType.TABLE;
  const isLogic = data.cardType === NodeCardType.LOGIC_NOTE;
  const isReport = data.cardType === NodeCardType.REPORT;

  const getTheme = () => {
    switch (data.cardType) {
      case NodeCardType.TABLE:
        return {
          header: 'bg-blue-600',
          body: 'bg-white',
          border: selected ? 'border-blue-500 ring-2 ring-blue-200' : 'border-blue-100',
          icon: <Database size={14} className="text-white" />,
          accent: 'text-blue-600'
        };
      case NodeCardType.LOGIC_NOTE:
        return {
          header: 'bg-purple-600',
          body: 'bg-white',
          border: selected ? 'border-purple-500 ring-2 ring-purple-200' : 'border-purple-100',
          icon: <FileText size={14} className="text-white" />,
          accent: 'text-purple-600'
        };
      default:
        return {
          header: 'bg-orange-600',
          body: 'bg-white',
          border: selected ? 'border-orange-500 ring-2 ring-orange-200' : 'border-orange-100',
          icon: <BarChart2 size={14} className="text-white" />,
          accent: 'text-orange-600'
        };
    }
  };

  const theme = getTheme();

  return (
    <div className={`min-w-[220px] max-w-[320px] rounded-xl overflow-hidden border shadow-sm transition-all duration-200 ${theme.border}`}>
      {/* Handles */}
      <Handle type="target" position={Position.Left} className="!w-3 !h-3" />
      <Handle type="source" position={Position.Right} className="!w-3 !h-3" />
      <Handle type="target" position={Position.Top} className="!w-3 !h-3" />
      <Handle type="source" position={Position.Bottom} className="!w-3 !h-3" />

      {/* Header */}
      <div className={`${theme.header} p-3 flex items-center justify-between text-white gap-3`}>
        <div className="flex items-center gap-2 overflow-hidden">
          <div className="p-1.5 bg-white/20 rounded backdrop-blur-sm flex-shrink-0">
            {theme.icon}
          </div>
          <h3 className="font-semibold text-sm truncate uppercase tracking-wider">{data.label}</h3>
        </div>
        <div className="flex items-center gap-1.5 ml-2">
          <button 
            onClick={() => data.onEdit?.(id)}
            className="p-1.5 hover:bg-white/20 rounded transition-colors"
          >
            <Edit3 size={12} />
          </button>
          <button 
            onClick={() => data.onDelete?.(id)}
            className="p-1.5 hover:bg-white/20 rounded transition-colors text-white/80 hover:text-white"
          >
            <Trash2 size={12} />
          </button>
        </div>
      </div>

      {/* Content Body */}
      <div className={`p-4 ${theme.body} max-h-[400px] overflow-y-auto custom-scrollbar`}>
        {isTable && (
          <div className="flex flex-col gap-1.5">
            {data.columns && data.columns.length > 0 ? (
              data.columns.map((col) => (
                <div key={col.id} className="flex items-center gap-3 py-1.5 px-2 hover:bg-slate-50 rounded-md group transition-colors">
                  <div className={`w-1.5 h-1.5 rounded-full ${theme.accent.replace('text', 'bg')}`} />
                  <span className="text-xs text-slate-600 font-medium">{col.name}</span>
                </div>
              ))
            ) : (
              <span className="text-xs text-slate-400 italic">No columns defined</span>
            )}
          </div>
        )}

        {(isLogic || isReport) && (
          <div className="flex flex-col gap-3">
            {data.description && (
              <p className="text-xs text-slate-500 leading-relaxed font-normal">
                {data.description}
              </p>
            )}
            {data.bulletPoints && data.bulletPoints.length > 0 && (
              <ul className="flex flex-col gap-1.5">
                {data.bulletPoints.map((point, idx) => (
                  <li key={idx} className="flex gap-2 text-xs text-slate-600">
                    <span className={theme.accent}>•</span>
                    <span>{point}</span>
                  </li>
                ))}
              </ul>
            )}
            {!data.description && (!data.bulletPoints || data.bulletPoints.length === 0) && (
              <span className="text-xs text-slate-400 italic">No content defined</span>
            )}
          </div>
        )}
      </div>
    </div>
  );
});

import React, { useState } from 'react';
import { X, Plus, Trash2, Database, FileText, BarChart2 } from 'lucide-react';
import { Node, NodeProps } from 'reactflow';
import { NodeData, NodeCardType, TableColumn } from '../types';

interface EditorModalProps {
  node: Node<NodeData>;
  onClose: () => void;
  onSave: (data: Partial<NodeData>) => void;
}

export const EditorModal: React.FC<EditorModalProps> = ({ node, onClose, onSave }) => {
  const [label, setLabel] = useState(node.data.label);
  const [cardType, setCardType] = useState<NodeCardType>(node.data.cardType);
  const [columns, setColumns] = useState<TableColumn[]>(node.data.columns || []);
  const [description, setDescription] = useState(node.data.description || '');
  const [bulletPoints, setBulletPoints] = useState<string[]>(node.data.bulletPoints || []);

  const handleAddColumn = () => {
    setColumns([...columns, { id: Date.now().toString(), name: 'New Column' }]);
  };

  const handleRemoveColumn = (id: string) => {
    setColumns(columns.filter(c => c.id !== id));
  };

  const handleUpdateColumn = (id: string, name: string) => {
    setColumns(columns.map(c => c.id === id ? { ...c, name } : c));
  };

  const handleAddBullet = () => {
    setBulletPoints([...bulletPoints, 'New point']);
  };

  const handleRemoveBullet = (index: number) => {
    setBulletPoints(bulletPoints.filter((_, i) => i !== index));
  };

  const handleUpdateBullet = (index: number, text: string) => {
    const newPoints = [...bulletPoints];
    newPoints[index] = text;
    setBulletPoints(newPoints);
  };

  const handleSave = () => {
    onSave({
      label,
      cardType,
      columns: cardType === NodeCardType.TABLE ? columns : [],
      description: (cardType === NodeCardType.LOGIC_NOTE || cardType === NodeCardType.REPORT) ? description : '',
      bulletPoints: (cardType === NodeCardType.LOGIC_NOTE || cardType === NodeCardType.REPORT) ? bulletPoints : []
    });
  };

  return (
    <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-xl rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
        {/* Modal Header */}
        <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
          <h2 className="text-lg font-bold text-slate-800">Edit Node Properties</h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 rounded-full transition-colors text-slate-400">
            <X size={20} />
          </button>
        </div>

        {/* Modal Body */}
        <div className="p-6 overflow-y-auto flex-1 space-y-6">
          {/* Label Input */}
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2">Node Name</label>
            <input 
              type="text" 
              value={label}
              onChange={(e) => setLabel(e.target.value)}
              className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all"
              placeholder="e.g. Sales Data"
            />
          </div>

          {/* Type Selector */}
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2">Node Type</label>
            <div className="grid grid-cols-3 gap-3">
              {[
                { type: NodeCardType.TABLE, icon: Database, label: 'Table', color: 'blue' },
                { type: NodeCardType.LOGIC_NOTE, icon: FileText, label: 'Logic Note', color: 'purple' },
                { type: NodeCardType.REPORT, icon: BarChart2, label: 'Report', color: 'orange' }
              ].map((item) => (
                <button
                  key={item.type}
                  onClick={() => setCardType(item.type)}
                  className={`flex flex-col items-center gap-2 p-3 rounded-xl border-2 transition-all ${
                    cardType === item.type 
                    ? `border-${item.color}-500 bg-${item.color}-50 text-${item.color}-700` 
                    : 'border-slate-100 bg-white text-slate-400 hover:border-slate-200'
                  }`}
                >
                  <item.icon size={24} />
                  <span className="text-xs font-bold">{item.label}</span>
                </button>
              ))}
            </div>
          </div>

          {/* Conditional Content */}
          <div className="pt-4 border-t border-slate-100">
            {cardType === NodeCardType.TABLE ? (
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <label className="text-sm font-semibold text-slate-700">Columns</label>
                  <button 
                    onClick={handleAddColumn}
                    className="text-xs font-bold text-blue-600 hover:text-blue-700 flex items-center gap-1"
                  >
                    <Plus size={14} /> Add Column
                  </button>
                </div>
                <div className="space-y-2">
                  {columns.map((col) => (
                    <div key={col.id} className="flex gap-2">
                      <input 
                        type="text"
                        value={col.name}
                        onChange={(e) => handleUpdateColumn(col.id, e.target.value)}
                        className="flex-1 px-3 py-1.5 border border-slate-200 rounded-lg text-sm"
                      />
                      <button 
                        onClick={() => handleRemoveColumn(col.id)}
                        className="p-2 text-slate-400 hover:text-red-500 transition-colors"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  ))}
                  {columns.length === 0 && (
                    <div className="py-8 text-center bg-slate-50 rounded-lg border border-dashed border-slate-200">
                      <span className="text-xs text-slate-400">No columns added yet.</span>
                    </div>
                  )}
                </div>
              </div>
            ) : (
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Description</label>
                  <textarea 
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                    rows={3}
                    className="w-full px-4 py-2 border border-slate-200 rounded-lg text-sm outline-none focus:ring-2 focus:ring-purple-500"
                    placeholder="Enter short description..."
                  />
                </div>
                <div>
                  <div className="flex items-center justify-between mb-2">
                    <label className="text-sm font-semibold text-slate-700">Key Points</label>
                    <button 
                      onClick={handleAddBullet}
                      className="text-xs font-bold text-purple-600 hover:text-purple-700 flex items-center gap-1"
                    >
                      <Plus size={14} /> Add Point
                    </button>
                  </div>
                  <div className="space-y-2">
                    {bulletPoints.map((point, idx) => (
                      <div key={idx} className="flex gap-2">
                        <input 
                          type="text"
                          value={point}
                          onChange={(e) => handleUpdateBullet(idx, e.target.value)}
                          className="flex-1 px-3 py-1.5 border border-slate-200 rounded-lg text-sm"
                        />
                        <button 
                          onClick={() => handleRemoveBullet(idx)}
                          className="p-2 text-slate-400 hover:text-red-500 transition-colors"
                        >
                          <Trash2 size={16} />
                        </button>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Modal Footer */}
        <div className="p-6 bg-slate-50 border-t border-slate-100 flex justify-end gap-3">
          <button 
            onClick={onClose}
            className="px-6 py-2 text-slate-600 font-semibold hover:bg-slate-200 rounded-xl transition-colors text-sm"
          >
            Cancel
          </button>
          <button 
            onClick={handleSave}
            className="px-6 py-2 bg-slate-800 text-white font-semibold hover:bg-slate-900 rounded-xl shadow-lg shadow-slate-200 transition-all text-sm"
          >
            Save Changes
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useCallback } from 'react';
import ReactFlow, { 
  Background, 
  Controls, 
  addEdge, 
  applyEdgeChanges, 
  applyNodeChanges,
  Node,
  Edge,
  Connection,
  EdgeChange,
  NodeChange,
  ReactFlowProvider,
  useReactFlow,
  Panel
} from 'reactflow';
import { Download, Upload, Plus } from 'lucide-react';
import * as XLSX from 'xlsx';

import { NodeCardType, NodeData } from './types';
import { BlueprintCard } from './components/BlueprintCard';
import { EditorModal } from './components/EditorModal';

const nodeTypes = {
  blueprintNode: BlueprintCard,
};

const initialNodes: Node<NodeData>[] = [
  {
    id: '1',
