          <h1 className="text-xl font-semibold text-slate-800 tracking-tight">Tax Data Blueprint Studio</h1>
        </div>

        <div className="flex items-center gap-3">
          <button 
            onClick={() => addNode(NodeCardType.TABLE)}
            className="flex items-center gap-2 px-3 py-1.5 bg-blue-50 text-blue-700 rounded-lg hover:bg-blue-100 transition-colors font-medium text-xs sm:text-sm"
          >
            <Plus size={16} />
            Add Table
          </button>
          <button 
            onClick={() => addNode(NodeCardType.LOGIC_NOTE)}
            className="flex items-center gap-2 px-3 py-1.5 bg-purple-50 text-purple-700 rounded-lg hover:bg-purple-100 transition-colors font-medium text-xs sm:text-sm"
