            <p className="text-[10px] text-slate-400 font-medium uppercase tracking-widest mt-1">Documentation & Visualization</p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <button 
            onClick={() => addNode(NodeCardType.TABLE)}
            className="flex items-center gap-2 px-3 py-1.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-all font-semibold text-xs shadow-sm hover:shadow-md"
          >
            <Plus size={16} />
            Add Table
