          <button 
            onClick={() => addNode(NodeCardType.LOGIC_NOTE)}
            className="flex items-center gap-2 px-3 py-1.5 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition-all font-semibold text-xs shadow-sm hover:shadow-md"
          >
            <Plus size={16} />
            Add Logic
          </button>
          <button 
            onClick={() => addNode(NodeCardType.REPORT)}
            className="flex items-center gap-2 px-3 py-1.5 bg-orange-600 text-white rounded-lg hover:bg-orange-700 transition-all font-semibold text-xs shadow-sm hover:shadow-md"
          >
            <Plus size={16} />
            Add Report
          </button>

          <div className="h-8 w-px bg-slate-200 mx-2" />

          <button 
            onClick={exportToExcel}
            className="flex items-center gap-2 px-3 py-1.5 bg-white border border-slate-200 text-slate-700 rounded-lg hover:border-slate-300 hover:bg-slate-50 transition-all font-semibold text-xs"
          >
            <Download size={16} />
            Export Project
          </button>
          <label className="flex items-center gap-2 px-3 py-1.5 bg-white border border-slate-200 text-slate-700 rounded-lg hover:border-slate-300 hover:bg-slate-50 transition-all font-semibold text-xs cursor-pointer">
            <Upload size={16} />
            Import
            <input type="file" className="hidden" accept=".xlsx, .xls" onChange={importFromExcel} />
          </label>
        </div>
      </header>

      {/* Canvas Area */}
      <div className="flex-1 min-h-0 relative">
        <ReactFlow
          nodes={nodesWithActions}
          edges={edges}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          onConnect={onConnect}
          nodeTypes={nodeTypes}
          fitView
          className="bg-slate-50"
          defaultEdgeOptions={{ type: 'smoothstep' }}
        >
          <Background color="#cbd5e1" variant={BackgroundVariant.Dots} gap={24} size={1} />
          <Controls />
          <Panel position="bottom-right" className="bg-white/95 backdrop-blur-sm p-3 rounded-xl shadow-xl border border-slate-200 flex flex-col gap-2 select-none min-w-[140px]">
