              </div>
              <div className="flex flex-col">
                <span className="text-sm font-bold text-slate-800">{edges.length}</span>
                <span className="text-[10px] text-slate-500 font-medium uppercase">Mappings</span>
              </div>
            </div>
          </Panel>
        </ReactFlow>
      </div>

      {/* Editor Modal */}
      {editingNode && (
        <EditorModal 
          node={nodes.find(n => n.id === editingNode)!} 
          onClose={() => setEditingNode(null)}
          onSave={(data) => handleSaveNode(editingNode, data)}
        />
