            </label>
          </div>
        </div>

        <div className="p-6 bg-slate-50 border-t border-slate-100 flex justify-end gap-3">
          <button onClick={onClose} className="px-6 py-2 text-slate-600 text-sm font-bold">Cancel</button>
          <button onClick={() => onSave({ typeId, label, hasArrow })} className="px-8 py-2 bg-slate-900 text-white rounded-xl text-sm font-bold shadow-lg shadow-slate-200">Commit Update</button>
