import React, { memo } from 'react';
import { Handle, Position, NodeProps } from 'reactflow';
import { Trash2, Edit3, Database, FileText, BarChart2 } from 'lucide-react';
import { NodeData, NodeCardType, GlobalSettings } from '../types.ts';

export const BlueprintCard = memo(({ data, id, selected }: NodeProps<NodeData & { settings: GlobalSettings }>) => {
  const isTable = data.cardType === NodeCardType.TABLE;
  const isLogic = data.cardType === NodeCardType.LOGIC_NOTE;

  // Resolve dynamic category color
  let headerColor = '#ea580c'; // Default for reports
  if (isTable) {
    const category = data.settings?.tableCategories.find(c => c.id === data.categoryId);
    headerColor = category ? category.color : '#2563eb';
  } else if (isLogic) {
    const category = data.settings?.logicCategories.find(c => c.id === data.categoryId);
    headerColor = category ? category.color : '#9333ea';
  }

  const getTheme = () => {
    const baseIcon = isTable ? <Database size={14} /> : (isLogic ? <FileText size={14} /> : <BarChart2 size={14} />);
    return {
      border: selected ? 'border-slate-900 ring-2 ring-slate-100' : 'border-slate-100',
      icon: baseIcon,
      accent: headerColor
    };
  };

  const theme = getTheme();

  return (
    <div className={`min-w-[220px] max-w-[320px] rounded-xl overflow-hidden border shadow-sm transition-all duration-200 bg-white ${theme.border}`}>
      <Handle type="target" position={Position.Left} className="!w-2 !h-2" />
      <Handle type="source" position={Position.Right} className="!w-2 !h-2" />
      <Handle type="target" position={Position.Top} className="!w-2 !h-2" />
      <Handle type="source" position={Position.Bottom} className="!w-2 !h-2" />

      <div style={{ backgroundColor: headerColor }} className="p-3 flex items-center justify-between text-white gap-3 transition-colors duration-300">
        <div className="flex items-center gap-2 overflow-hidden">
          <div className="p-1.5 bg-white/20 rounded backdrop-blur-sm flex-shrink-0">{theme.icon}</div>
          <h3 className="font-bold text-xs truncate uppercase tracking-widest">{data.label}</h3>
        </div>
        <div className="flex items-center gap-1.5 ml-2">
          <button onClick={() => data.onEdit?.(id)} className="p-1 hover:bg-white/20 rounded transition-colors"><Edit3 size={12} /></button>
          <button onClick={() => data.onDelete?.(id)} className="p-1 hover:bg-white/20 rounded transition-colors"><Trash2 size={12} /></button>
        </div>
      </div>

      <div className="p-4 max-h-[400px] overflow-y-auto custom-scrollbar">
        {isTable ? (
          <div className="flex flex-col gap-1.5">
            {data.columns?.map(col => (
              <div key={col.id} className="flex items-center gap-3 py-1.5 px-2 hover:bg-slate-50 rounded-md transition-colors">
                <div className="w-1 h-1 rounded-full" style={{ backgroundColor: headerColor }} />
                <span className="text-[10px] text-slate-600 font-bold uppercase tracking-tight">{col.name}</span>
              </div>
            ))}
          </div>
        ) : (
          <div className="space-y-3">
            <p className="text-[11px] text-slate-500 leading-relaxed font-medium">{data.description}</p>
            {data.bulletPoints?.map((p, idx) => (
              <div key={idx} className="flex gap-2 text-[10px] text-slate-600">
                <span style={{ color: headerColor }}>•</span>
                <span>{p}</span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
});

import React, { useState } from 'react';
import { X, Plus, Trash2, Database, FileText, BarChart2, Tag } from 'lucide-react';
import { Node } from 'reactflow';
import { NodeData, NodeCardType, TableColumn, GlobalSettings } from '../types.ts';

interface EditorModalProps {
  node: Node<NodeData>;
  settings: GlobalSettings;
  onClose: () => void;
  onSave: (data: Partial<NodeData>) => void;
}

export const EditorModal: React.FC<EditorModalProps> = ({ node, settings, onClose, onSave }) => {
  const [label, setLabel] = useState(node.data.label);
  const [cardType, setCardType] = useState<NodeCardType>(node.data.cardType);

  // Determine initial category ID based on card type
  const initialCatId = node.data.categoryId || (
    cardType === NodeCardType.TABLE 
      ? (settings.tableCategories.find(c => c.isDefault) || settings.tableCategories[0]).id
      : (settings.logicCategories.find(c => c.isDefault) || settings.logicCategories[0]).id
  );

  const [categoryId, setCategoryId] = useState(initialCatId);
  const [columns, setColumns] = useState<TableColumn[]>(node.data.columns || []);
  const [description, setDescription] = useState(node.data.description || '');
  const [bulletPoints, setBulletPoints] = useState<string[]>(node.data.bulletPoints || []);

  const isTable = cardType === NodeCardType.TABLE;
  const isLogic = cardType === NodeCardType.LOGIC_NOTE;

  return (
    <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-xl rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
        <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
          <h2 className="text-lg font-bold text-slate-800 tracking-tight">Node Properties</h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={20} /></button>
        </div>

        <div className="p-6 overflow-y-auto flex-1 space-y-6">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1.5">Component Identity</label>
              <input type="text" value={label} onChange={e => setLabel(e.target.value)} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold focus:ring-2 focus:ring-blue-500 outline-none" />
            </div>
            {(isTable || isLogic) && (
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1.5 flex items-center gap-1.5"><Tag size={10} /> Category</label>
                <select value={categoryId} onChange={e => setCategoryId(e.target.value)} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold focus:ring-2 focus:ring-blue-500 outline-none">
                  {isTable ? (
                    settings.tableCategories.map(cat => (
                      <option key={cat.id} value={cat.id}>{cat.name}</option>
                    ))
                  ) : (
                    settings.logicCategories.map(cat => (
                      <option key={cat.id} value={cat.id}>{cat.name}</option>
                    ))
                  )}
                </select>
              </div>
            )}
          </div>

          <div className="pt-6 border-t border-slate-100">
            {isTable ? (
              <div className="space-y-4">
                <div className="flex items-center justify-between"><span className="text-sm font-bold text-slate-700">Fields & Schema</span><button onClick={() => setColumns([...columns, { id: Date.now().toString(), name: 'New Field' }])} className="text-xs font-bold text-blue-600 flex items-center gap-1"><Plus size={14} /> Add Field</button></div>
                <div className="space-y-2">
                  {columns.map(col => (
                    <div key={col.id} className="flex gap-2">
                      <input type="text" value={col.name} onChange={e => setColumns(columns.map(c => c.id === col.id ? { ...c, name: e.target.value } : c))} className="flex-1 px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-lg text-xs font-bold uppercase tracking-tight" />
                      <button onClick={() => setColumns(columns.filter(c => c.id !== col.id))} className="p-2 text-slate-300 hover:text-red-500"><Trash2 size={14} /></button>
                    </div>
                  ))}
                </div>
              </div>
            ) : (
              <div className="space-y-4">
                <div><label className="block text-sm font-bold text-slate-700 mb-2">Internal Logic</label><textarea value={description} onChange={e => setDescription(e.target.value)} rows={3} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-medium" /></div>
                <div className="flex items-center justify-between"><span className="text-sm font-bold text-slate-700">Directives</span><button onClick={() => setBulletPoints([...bulletPoints, 'New Point'])} className="text-xs font-bold text-purple-600 flex items-center gap-1"><Plus size={14} /> Add Point</button></div>
                {bulletPoints.map((p, idx) => (
                  <div key={idx} className="flex gap-2">
                    <input type="text" value={p} onChange={e => { const b = [...bulletPoints]; b[idx] = e.target.value; setBulletPoints(b); }} className="flex-1 px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-lg text-xs" />
                    <button onClick={() => setBulletPoints(bulletPoints.filter((_, i) => i !== idx))} className="p-2 text-slate-300 hover:text-red-500"><Trash2 size={14} /></button>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="p-6 bg-slate-50 border-t border-slate-100 flex justify-end gap-3">
          <button onClick={onClose} className="px-6 py-2 text-slate-600 text-sm font-bold">Cancel</button>
          <button onClick={() => onSave({ label, categoryId, columns, description, bulletPoints })} className="px-8 py-2 bg-slate-900 text-white rounded-xl text-sm font-bold shadow-lg">Commit Update</button>
        </div>
      </div>
    </div>
  );
};

